ALTER TABLE "efa_dispatch" ADD CONSTRAINT "efa_dispatch_state_allowed" CHECK (("efa_dispatch"."state" = 'draft' and "efa_dispatch"."finalized_at" is null and "efa_dispatch"."cancelled_at" is null and "efa_dispatch"."cancelled_from_state" is null) or ("efa_dispatch"."state" = 'finalized' and "efa_dispatch"."finalized_at" is not null and "efa_dispatch"."priority" is not null and "efa_dispatch"."result" is not null and "efa_dispatch"."cancelled_at" is null and "efa_dispatch"."cancelled_from_state" is null) or ("efa_dispatch"."state" = 'cancelled' and "efa_dispatch"."cancelled_at" is not null and "efa_dispatch"."cancelled_from_state" in ('draft','finalized') and (("efa_dispatch"."cancelled_from_state" = 'draft' and "efa_dispatch"."finalized_at" is null) or ("efa_dispatch"."cancelled_from_state" = 'finalized' and "efa_dispatch"."finalized_at" is not null and "efa_dispatch"."priority" is not null and "efa_dispatch"."result" is not null))));--> statement-breakpoint
ALTER TABLE "efa_dispatch_audit" ADD CONSTRAINT "efa_dispatch_audit_action_allowed" CHECK ("efa_dispatch_audit"."action" in ('created','updated','finalized','cancelled','reactivated'));--> statement-breakpoint
ALTER TABLE "efa_dispatch_operation" ADD CONSTRAINT "efa_dispatch_operation_action_allowed" CHECK ("efa_dispatch_operation"."action" in ('created','updated','finalized','cancelled','reactivated'));